item.text:
[
  {
    "task_id": "ctx-k2-2",
    "params": {
      "keysel": [0, 0, 9, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Column colour sets govern recolouring: demonstration 1 turns zeros into 3 in columns containing only 1; demonstration 3 turns 1 and 2 into 8 in columns containing {1,2}, and 3 into 9 in a column containing {2,3}."
  },
  {
    "task_id": "ctx-k2-3",
    "params": {
      "keysel": [0, 0, 9, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstration 1 maps zeros to 5 in {1,3} columns and maps zero to 8 and 2 to 7 in {1,2,3} columns. Demonstration 3 maps 2 to 0 in {2,3} columns."
  },
  {
    "task_id": "ctx-k2-0",
    "params": {
      "keysel": [0, 0, 9, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstration 3 maps zero to 2 in {1,3} columns and 1 to 0 in {1,2,3} columns. Demonstration 7 maps 2 to 9 in its {1,2} first column."
  },
  {
    "task_id": "ctx-k0-1",
    "params": {
      "keysel": [9, 0, 0, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstrations 3 and 4 change the top-left zero to 6 when its in-grid 2x2 neighbourhood is entirely zero. The full 3x3 key includes the missing top and left neighbours."
  },
  {
    "task_id": "ctx-k0-2",
    "params": {
      "keysel": [9, 0, 0, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstrations 6 and 8 change the top-right zero to 4 when the adjoining in-grid 2x2 block is all zero; their identical 3x3 keys include missing top and right neighbours."
  },
  {
    "task_id": "ctx-k2-1",
    "params": {
      "keysel": [0, 0, 9, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstration 1 maps zero to 4 in {1,3} columns. Demonstration 2 maps zero and 3 to 6 in {1,2,3} columns and zero to 9 in its column containing only 3."
  },
  {
    "task_id": "ctx-k6-1",
    "params": {
      "keysel": [0, 0, 0, 0, 0, 0, 9, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstration 1 changes zero to 1 with nearest directional colours (missing,1,3,3). Demonstrations 9 and 10 change zero to 9 with directional colours (missing,3,2,missing), looking up, down, left, right."
  },
  {
    "task_id": "ctx-k0-3",
    "params": {
      "keysel": [9, 0, 0, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Demonstration 10 changes the zero at row 2, column 7 to 4. Its 3x3 pattern is [[0,0,-1],[0,0,-1],[0,1,-1]], identifying the right-edge neighbourhood."
  },
  {
    "task_id": "ctx-k5-1",
    "params": {
      "keysel": [0, 0, 0, 0, 0, 9, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Every demonstration recolours border pixels by 0→5, 1→6, 2→1, 3→9 while preserving interior pixels; demonstration 1 shows all four border mappings."
  },
  {
    "task_id": "ctx-k3-3",
    "params": {
      "keysel": [0, 0, 0, 9, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "With row set {1,2,3}, 2 becomes 3 when the column set is {1,2,3}, as in demonstration 2, and becomes 4 when the column set is {2,3}, as in demonstration 5. Demonstration 3 maps zero to 9 where the row set is {1} and column set is {1,2,3}."
  }
]
